const apiUrl=(import.meta.env.VITE_API_URL??'http://localhost:3300/api/v1').replace(/\/$/,'')
async function api<T>(path:string,init?:RequestInit){const token=localStorage.getItem('orbitask_token');const response=await fetch(`${apiUrl}${path}`,{...init,headers:{'Content-Type':'application/json',...(token?{Authorization:`Bearer ${token}`}:{})}});const body=await response.json().catch(()=>null);if(!response.ok)throw new Error(body?.message??'Não foi possível concluir');return body as T}

function WebReportsPage(){
  const [report,setReport]=useState<DashboardReport|null>(null),[error,setError]=useState('')
  useEffect(()=>{api<DashboardReport>('/reports/dashboard').then(setReport).catch(e=>setError(e instanceof Error?e.message:'Não foi possível carregar os indicadores'))},[])
  if(error)return <div className="web-insight-state"><BarChart3/><h2>Indicadores indisponíveis</h2><p>{error}</p></div>
  if(!report)return <div className="web-insight-state"><span className="web-spinner"/><h2>Preparando sua visão geral</h2></div>
  const completion=report.totals.tasks?Math.round(report.totals.completed/report.totals.tasks*100):0,maxStatus=Math.max(1,...report.byStatus.map(item=>item.count))
  const kpis:{Icon:LucideIcon;label:string;value:number;hint:string}[]=[{Icon:FolderKanban,label:'Projetos',value:report.totals.projects,hint:'Em acompanhamento'},{Icon:ListChecks,label:'Tarefas ativas',value:report.totals.active,hint:'Trabalho em execução'},{Icon:CheckCircle2,label:'Concluídas',value:report.totals.completed,hint:'Entregas realizadas'},{Icon:Clock3,label:'Atrasadas',value:report.totals.overdue,hint:report.totals.dueSoon?`${report.totals.dueSoon} vencem em 7 dias`:'Nenhuma próxima do prazo'}]
  return <section className="web-reports-page"><header className="web-insight-hero"><div><small>PAINEL DO WORKSPACE</small><h1>Visão geral</h1><p>Saúde do trabalho, entregas e capacidade da equipe em um só lugar.</p></div><div className="web-health-score"><span style={{'--score':`${completion*3.6}deg`} as React.CSSProperties}><b>{completion}%</b></span><div><strong>Progresso geral</strong><small>{report.totals.completed} de {report.totals.tasks} tarefas concluídas</small></div></div></header>
    <div className="web-kpi-grid">{kpis.map(({Icon,label,value,hint})=><article key={label} className={label==='Atrasadas'&&value>0?'danger':''}><span><Icon/></span><div><small>{label}</small><strong>{value}</strong><p>{hint}</p></div></article>)}</div>
    <div className="web-report-grid"><article className="web-report-card"><header><div><small>FLUXO DE TRABALHO</small><h2>Tarefas por status</h2></div><BarChart3/></header><div className="web-status-bars">{report.byStatus.map(item=><div key={item.id}><label><span><i style={{background:item.color}}/>{item.name}</span><strong>{item.count}</strong></label><span><i style={{width:`${item.count/maxStatus*100}%`,background:item.color}}/></span></div>)}</div></article>
      <article className="web-report-card"><header><div><small>ATENÇÃO</small><h2>Distribuição por prioridade</h2></div><Target/></header><div className="web-priority-donut"><span style={{background:`conic-gradient(${report.byPriority.map((item,index)=>`${item.color} ${report.byPriority.slice(0,index).reduce((n,x)=>n+x.count,0)/Math.max(1,report.totals.tasks)*100}% ${report.byPriority.slice(0,index+1).reduce((n,x)=>n+x.count,0)/Math.max(1,report.totals.tasks)*100}%`).join(',')})`}}><i>{report.totals.tasks}</i></span><div>{report.byPriority.map(item=><label key={item.id}><i style={{background:item.color}}/><b>{item.name}</b><em>{item.count}</em></label>)}</div></div></article>
    </div>
    <div className="web-report-grid lower"><article className="web-report-card"><header><div><small>PROJETOS</small><h2>Progresso e risco</h2></div><FolderKanban/></header><div className="web-project-health">{report.projects.map(project=><div key={project.id}><span className="web-report-project-icon" style={{background:project.color}}><ProjectGlyph name={project.icon}/></span><div><label><strong>{project.name}</strong><small>{project.completed}/{project.total} concluídas</small></label><span><i style={{width:`${project.progress}%`,background:project.color}}/></span></div><b>{project.progress}%</b>{project.overdue>0&&<em>{project.overdue} atrasada(s)</em>}</div>)}</div></article>
      <article className="web-report-card"><header><div><small>EQUIPE</small><h2>Carga por responsável</h2></div><Users/></header>{report.byAssignee.length?<div className="web-workload">{report.byAssignee.map(person=><div key={person.id}><span>{person.avatarUrl?<img src={person.avatarUrl}/>:person.name.slice(0,2).toUpperCase()}</span><div><strong>{person.name}</strong><small>{person.completed} concluídas · {person.overdue} atrasadas</small></div><b>{person.count}</b></div>)}</div>:<div className="web-report-empty"><Users/><p>Atribua responsáveis para visualizar a carga da equipe.</p></div>}</article></div>
  </section>
}

const healthLabels:Record<PortfolioHealth,string>={on_track:'Em dia',at_risk:'Em risco',off_track:'Atrasado',on_hold:'Pausado'}
const goalLabels:Record<GoalStatus,string>={not_started:'Não iniciada',on_track:'Em dia',at_risk:'Em risco',completed:'Concluída'}
function WebPortfoliosPage({snapshot}:{snapshot:WorkspaceSnapshot}){
  const [data,setData]=useState<PortfolioOverview|null>(null),[mode,setMode]=useState<'portfolio'|'goal'|null>(null),[editingPortfolio,setEditingPortfolio]=useState<Portfolio|null>(null),[editingGoal,setEditingGoal]=useState<Goal|null>(null),[error,setError]=useState('')
  const load=()=>api<PortfolioOverview>('/portfolio-overview').then(setData).catch(e=>setError(e instanceof Error?e.message:'Não foi possível carregar'))
  useEffect(()=>{load()},[])
  const metrics=new Map(data?.projectMetrics.map(item=>[item.id,item])??[]),admin=snapshot.workspace.role==='admin'
  const portfolioProgress=(item:Portfolio)=>{const list=item.projectIds.map(id=>metrics.get(id)).filter(Boolean);return list.length?Math.round(list.reduce((n,x)=>n+x!.progress,0)/list.length):0}
  const remove=async(kind:'portfolios'|'goals',id:string)=>{await api(`/${kind}/${id}`,{method:'DELETE'});await load()}
  return <section className="web-portfolios-page"><header className="web-insight-hero"><div><small>ESTRATÉGIA</small><h1>Portfólios e metas</h1><p>Conecte projetos à estratégia e acompanhe saúde, prazo e progresso.</p></div>{admin&&<div className="web-strategy-actions"><button onClick={()=>{setEditingGoal(null);setMode('goal')}}><Target/> Nova meta</button><button className="primary" onClick={()=>{setEditingPortfolio(null);setMode('portfolio')}}><Plus/> Novo portfólio</button></div>}</header>
    {error&&<div className="web-error">{error}</div>}
    <section className="web-strategy-section"><header><div><small>VISÃO EXECUTIVA</small><h2>Portfólios</h2></div><span>{data?.portfolios.length??0} grupos estratégicos</span></header>{data?.portfolios.length?<div className="web-portfolio-grid">{data.portfolios.map(item=>{const progress=portfolioProgress(item);return <article key={item.id} style={{'--portfolio':item.color} as React.CSSProperties}><header><span><BriefcaseBusiness/></span><div><small>{healthLabels[item.health]}</small><h3>{item.name}</h3></div>{admin&&<button onClick={()=>{setEditingPortfolio(item);setMode('portfolio')}}><MoreHorizontal/></button>}</header><p>{item.description||'Agrupe projetos relacionados para acompanhar o resultado.'}</p><div className="web-portfolio-progress"><label><span>Progresso</span><b>{progress}%</b></label><span><i style={{width:`${progress}%`}}/></span></div><footer><span>{item.projectIds.length} projeto(s)</span>{item.dueDate&&<span><CalendarDays/> {new Date(`${item.dueDate}T12:00:00`).toLocaleDateString('pt-BR')}</span>}</footer></article>})}</div>:<div className="web-strategy-empty"><BriefcaseBusiness/><h3>Organize iniciativas relacionadas</h3><p>Crie um portfólio para reunir projetos e enxergar o progresso agregado.</p>{admin&&<button onClick={()=>setMode('portfolio')}><Plus/> Criar primeiro portfólio</button>}</div>}</section>
    <section className="web-strategy-section"><header><div><small>OBJETIVOS</small><h2>Metas do workspace</h2></div><span>{data?.goals.filter(goal=>goal.status!=='completed').length??0} em andamento</span></header>{data?.goals.length?<div className="web-goal-list">{data.goals.map(item=><article key={item.id}><span className={`web-goal-status ${item.status}`}>{goalLabels[item.status]}</span><div><h3>{item.title}</h3><p>{item.description||`${item.projectIds.length} projeto(s) conectado(s)`}</p><span><i style={{width:`${item.progress}%`}}/></span></div><strong>{item.progress}%</strong>{item.dueDate&&<small>{new Date(`${item.dueDate}T12:00:00`).toLocaleDateString('pt-BR')}</small>}{admin&&<button onClick={()=>{setEditingGoal(item);setMode('goal')}}><MoreHorizontal/></button>}</article>)}</div>:<div className="web-strategy-empty compact"><Target/><h3>Transforme estratégia em resultado</h3><p>Defina metas mensuráveis e vincule os projetos responsáveis.</p></div>}</section>
    {mode&&<WebStrategyModal kind={mode} snapshot={snapshot} portfolio={editingPortfolio} goal={editingGoal} onClose={()=>setMode(null)} onSaved={async()=>{setMode(null);await load()}} onRemove={remove}/>}</section>
}

function WebStrategyModal({kind,snapshot,portfolio,goal,onClose,onSaved,onRemove}:{kind:'portfolio'|'goal';snapshot:WorkspaceSnapshot;portfolio:Portfolio|null;goal:Goal|null;onClose:()=>void;onSaved:()=>Promise<void>;onRemove:(kind:'portfolios'|'goals',id:string)=>Promise<void>}){
  const [name,setName]=useState(portfolio?.name??goal?.title??''),[description,setDescription]=useState(portfolio?.description??goal?.description??''),[color,setColor]=useState(portfolio?.color??'#665cf6'),[status,setStatus]=useState<PortfolioHealth|GoalStatus>(portfolio?.health??goal?.status??(kind==='portfolio'?'on_track':'not_started')),[progress,setProgress]=useState(goal?.progress??0),[dueDate,setDueDate]=useState(portfolio?.dueDate??goal?.dueDate??''),[projectIds,setProjectIds]=useState(portfolio?.projectIds??goal?.projectIds??[]),[busy,setBusy]=useState(false),[error,setError]=useState('')
  const submit=async(e:FormEvent)=>{e.preventDefault();setBusy(true);setError('');try{if(kind==='portfolio')await api('/portfolios',{method:'POST',body:JSON.stringify({id:portfolio?.id,name,description,color,health:status,dueDate:dueDate||null,projectIds})});else await api('/goals',{method:'POST',body:JSON.stringify({id:goal?.id,title:name,description,status,progress,dueDate:dueDate||null,projectIds})});await onSaved()}catch(e){setError(e instanceof Error?e.message:'Não foi possível salvar')}finally{setBusy(false)}}
  const existing=portfolio?.id??goal?.id
  return <div className="web-modal-backdrop" onMouseDown={e=>e.target===e.currentTarget&&onClose()}><form className="web-strategy-modal" onSubmit={submit}><header><div><small>{kind==='portfolio'?'PORTFÓLIO':'META'}</small><h2>{existing?'Editar':'Criar'} {kind==='portfolio'?'portfólio':'meta'}</h2></div><button type="button" onClick={onClose}><X/></button></header><label>{kind==='portfolio'?'Nome':'Título'}<input autoFocus required value={name} onChange={e=>setName(e.target.value)}/></label><label>Descrição<textarea rows={3} value={description} onChange={e=>setDescription(e.target.value)}/></label><div className="web-task-fields"><label>Status<select value={status} onChange={e=>setStatus(e.target.value as PortfolioHealth|GoalStatus)}>{Object.entries(kind==='portfolio'?healthLabels:goalLabels).map(([id,label])=><option key={id} value={id}>{label}</option>)}</select></label><label>Prazo<input type="date" value={dueDate} onChange={e=>setDueDate(e.target.value)}/></label></div>{kind==='portfolio'?<label>Cor<input className="web-color-field" type="color" value={color} onChange={e=>setColor(e.target.value)}/></label>:<label>Progresso <strong>{progress}%</strong><input type="range" min="0" max="100" step="5" value={progress} onChange={e=>setProgress(Number(e.target.value))}/></label>}<fieldset className="web-strategy-projects"><legend>Projetos vinculados</legend>{snapshot.projects.map(project=><label key={project.id}><input type="checkbox" checked={projectIds.includes(project.id)} onChange={()=>setProjectIds(projectIds.includes(project.id)?projectIds.filter(id=>id!==project.id):[...projectIds,project.id])}/><i style={{background:project.color}}><ProjectGlyph name={project.icon}/></i><span>{project.name}</span></label>)}</fieldset>{error&&<div className="web-error">{error}</div>}<footer>{existing&&<button type="button" className="web-danger-button" onClick={async()=>{await onRemove(kind==='portfolio'?'portfolios':'goals',existing);onClose()}}><Trash2/> Excluir</button>}<span/><button type="button" onClick={onClose}>Cancelar</button><button className="web-save-task" disabled={busy}>{busy?'Salvando...':'Salvar'}</button></footer></form></div>
}

function WebTeamPage({snapshot,session,onRefresh,onSession}:{snapshot:WorkspaceSnapshot;session:AuthSession;onRefresh:()=>Promise<void>;onSession:(session:AuthSession)=>void}){
  const [invite,setInvite]=useState({email:'',role:'member' as WorkspaceRole,projectIds:[] as string[]})
  const [profile,setProfile]=useState({name:session.user.name,avatarUrl:session.user.avatarUrl??''})
  const [inviteUrl,setInviteUrl]=useState(''),[error,setError]=useState(''),[busy,setBusy]=useState(false)
  const admin=session.workspace.role==='admin'
  const createInvite=async(e:FormEvent)=>{e.preventDefault();setBusy(true);setError('');try{const created=await api<WorkspaceInvite>('/workspace/invites',{method:'POST',body:JSON.stringify(invite)});setInviteUrl(created.inviteUrl??'');setInvite({email:'',role:'member',projectIds:[]});await onRefresh()}catch(e){setError(e instanceof Error?e.message:'Não foi possível criar o convite')}finally{setBusy(false)}}
  const updateMember=async(member:WorkspaceMember,role:WorkspaceRole)=>{setError('');try{await api(`/workspace/members/${member.userId}`,{method:'PATCH',body:JSON.stringify({role,projectIds:role==='guest'?(member.projectIds.length?member.projectIds:[snapshot.project.id]):[]})});await onRefresh()}catch(e){setError(e instanceof Error?e.message:'Não foi possível atualizar o membro')}}
  const saveProfile=async(e:FormEvent)=>{e.preventDefault();setBusy(true);setError('');try{const user=await api<AuthSession['user']>('/profile',{method:'PATCH',body:JSON.stringify({...profile,avatarUrl:profile.avatarUrl||null})});onSession({...session,user});await onRefresh()}catch(e){setError(e instanceof Error?e.message:'Não foi possível salvar o perfil')}finally{setBusy(false)}}
  return <section className="web-team-page"><header><div><small>WORKSPACE</small><h1>Pessoas e acesso</h1><p>Gerencie quem participa, o papel de cada pessoa e o acesso de convidados aos projetos.</p></div><span>{snapshot.members.length} membro(s)</span></header>
    <div className="web-team-grid"><section className="web-team-card"><h2>Equipe</h2><div className="web-member-list">{snapshot.members.map(member=><article key={member.userId}><span className="web-member-avatar">{member.avatarUrl?<img src={member.avatarUrl}/>:member.name.slice(0,2).toUpperCase()}</span><div><strong>{member.name}</strong><small>{member.email}</small>{member.role==='guest'&&<em>{member.projectIds.length} projeto(s)</em>}</div>{admin?<><select value={member.role} onChange={e=>updateMember(member,e.target.value as WorkspaceRole)}><option value="admin">Administrador</option><option value="member">Membro</option><option value="guest">Convidado</option></select>{member.userId!==session.user.id&&<button onClick={async()=>{await api(`/workspace/members/${member.userId}`,{method:'DELETE'});await onRefresh()}}>Remover</button>}</>:<span>{member.role}</span>}</article>)}</div></section>
      {admin&&<section className="web-team-card"><h2>Convidar pessoa</h2><p>Crie um convite seguro, válido por sete dias.</p><form onSubmit={createInvite}><label>E-mail<input type="email" required value={invite.email} onChange={e=>setInvite({...invite,email:e.target.value})}/></label><label>Papel<select value={invite.role} onChange={e=>setInvite({...invite,role:e.target.value as WorkspaceRole,projectIds:[]})}><option value="member">Membro</option><option value="admin">Administrador</option><option value="guest">Convidado</option></select></label>{invite.role==='guest'&&<fieldset><legend>Projetos permitidos</legend>{snapshot.projects.map(project=><label key={project.id}><input type="checkbox" checked={invite.projectIds.includes(project.id)} onChange={()=>setInvite({...invite,projectIds:invite.projectIds.includes(project.id)?invite.projectIds.filter(id=>id!==project.id):[...invite.projectIds,project.id]})}/>{project.name}</label>)}</fieldset>}<button disabled={busy}>Criar convite</button></form>{inviteUrl&&<div className="web-invite-link"><input readOnly value={inviteUrl}/><button onClick={()=>navigator.clipboard.writeText(inviteUrl)}>Copiar link</button></div>}</section>}
      <section className="web-team-card"><h2>Seu perfil</h2><form onSubmit={saveProfile}><label>Nome<input required value={profile.name} onChange={e=>setProfile({...profile,name:e.target.value})}/></label><label>URL do avatar<input type="url" value={profile.avatarUrl} onChange={e=>setProfile({...profile,avatarUrl:e.target.value})} placeholder="https://..."/></label><button disabled={busy}>Salvar perfil</button></form></section>
      {admin&&snapshot.invites.length>0&&<section className="web-team-card"><h2>Convites pendentes</h2>{snapshot.invites.map(item=><article className="web-pending-invite" key={item.id}><div><strong>{item.email}</strong><small>{item.role} · expira em {new Date(item.expiresAt).toLocaleDateString('pt-BR')}</small></div><button onClick={async()=>{await api(`/workspace/invites/${item.id}`,{method:'DELETE'});await onRefresh()}}>Revogar</button></article>)}</section>}
    </div>{error&&<div className="web-error">{error}</div>}</section>
}

function WebInboxPage({snapshot,onOpen}:{snapshot:WorkspaceSnapshot;onOpen:(task:Task)=>void}){const [items,setItems]=useState<Notification[]>([]),[loading,setLoading]=useState(true);const load=async()=>{setItems(await api<Notification[]>('/notifications'));setLoading(false)};useEffect(()=>{load()},[]);const open=async(item:Notification)=>{if(!item.readAt){await api(`/notifications/${item.id}/read`,{method:'PATCH'});await load()}const task=snapshot.tasks.find(task=>task.id===item.taskId);if(task)onOpen(task)};return <section className="web-inbox-page"><header><div><small>ATUALIZAÇÕES</small><h1>Caixa de entrada</h1><p>Mudanças nas tarefas que você segue ou pelas quais é responsável.</p></div><button onClick={async()=>{await api('/notifications/read-all',{method:'PATCH'});await load()}}><Check/> Marcar tudo como lido</button></header><div>{loading?<p>Carregando...</p>:items.length?items.map(item=><button className={item.readAt?'read':''} key={item.id} onClick={()=>open(item)}><i/><span><strong>{item.title}</strong><p>{item.message}</p><small>{new Date(item.createdAt).toLocaleDateString('pt-BR',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'})}</small></span><ChevronDown/></button>):<div className="web-inbox-empty"><Bell/><h2>Tudo em dia</h2><p>Novas atualizações aparecerão aqui.</p></div>}</div></section>}

const webFieldLabels:Record<CustomFieldType,string>={text:'Texto',number:'Número',date:'Data',single:'Seleção única',multi:'Seleção múltipla'}
const webFieldColors=['#665cf6','#e45f65','#ee9b3b','#2ca87f','#3388d8','#9b59b6']
function WebCustomFieldsModal({snapshot,onClose,onRefresh}:{snapshot:WorkspaceSnapshot;onClose:()=>void;onRefresh:()=>Promise<void>}){
  const [fields,setFields]=useState(snapshot.customFields.map(field=>({...field,options:field.options.map(option=>({...option}))}))),[busy,setBusy]=useState(false),[error,setError]=useState('')
  const add=(type:CustomFieldType)=>setFields(current=>[...current,{id:crypto.randomUUID(),projectId:snapshot.project.id,name:`Novo campo de ${webFieldLabels[type].toLowerCase()}`,type,options:type==='single'||type==='multi'?[{id:crypto.randomUUID(),label:'Opção 1',color:webFieldColors[0]}]:[],position:current.length}])
  const update=(index:number,change:Partial<CustomFieldDefinition>)=>setFields(current=>current.map((field,i)=>i===index?{...field,...change}:field))
  const save=async()=>{setBusy(true);setError('');try{await api(`/projects/${snapshot.project.id}/custom-fields`,{method:'PATCH',body:JSON.stringify({fields})});await onRefresh();onClose()}catch(e){setError(e instanceof Error?e.message:'Não foi possível salvar os campos')}finally{setBusy(false)}}
  return <div className="web-modal-backdrop" onMouseDown={e=>e.target===e.currentTarget&&onClose()}><div className="web-custom-fields-modal"><header><div><small>CONFIGURAÇÕES DO PROJETO</small><h2>Campos personalizados</h2><p>Crie dados próprios para cards, lista e filtros.</p></div><button onClick={onClose}><X/></button></header><div className="web-add-field">{Object.entries(webFieldLabels).map(([type,label])=><button key={type} onClick={()=>add(type as CustomFieldType)}><Plus/>{label}</button>)}</div><div className="web-field-definitions">{fields.map((field,index)=><article key={field.id}><div><input value={field.name} onChange={e=>update(index,{name:e.target.value})}/><span>{webFieldLabels[field.type]}</span><button onClick={()=>setFields(current=>current.filter(item=>item.id!==field.id))}><Trash2/></button></div>{(field.type==='single'||field.type==='multi')&&<section>{field.options.map((option,optionIndex)=><label key={option.id}><input type="color" value={option.color} onChange={e=>update(index,{options:field.options.map((item,i)=>i===optionIndex?{...item,color:e.target.value}:item)})}/><input value={option.label} onChange={e=>update(index,{options:field.options.map((item,i)=>i===optionIndex?{...item,label:e.target.value}:item)})}/><button onClick={()=>update(index,{options:field.options.filter(item=>item.id!==option.id)})}><X/></button></label>)}<button onClick={()=>update(index,{options:[...field.options,{id:crypto.randomUUID(),label:`Opção ${field.options.length+1}`,color:webFieldColors[field.options.length%webFieldColors.length]}]})}><Plus/>Adicionar opção</button></section>}</article>)}{!fields.length&&<div className="web-fields-empty"><Workflow/><strong>Nenhum campo criado</strong><p>Escolha um tipo acima para começar.</p></div>}</div>{error&&<div className="web-error">{error}</div>}<footer><button onClick={onClose}>Cancelar</button><button className="web-save-task" disabled={busy} onClick={save}>{busy?'Salvando...':'Salvar campos'}</button></footer></div></div>
}
function WebTaskCustomFields({snapshot,task,onRefresh}:{snapshot:WorkspaceSnapshot;task:Task;onRefresh:()=>Promise<void>}){const value=(id:string)=>snapshot.customFieldValues.find(item=>item.taskId===task.id&&item.fieldId===id)?.value??null;const save=async(fieldId:string,next:string|number|string[]|null)=>{await api(`/tasks/${task.id}/custom-fields/${fieldId}`,{method:'PATCH',body:JSON.stringify({value:next})});await onRefresh()};if(!snapshot.customFields.length)return null;return <section className="web-task-custom-fields"><header><div><Workflow/><strong>Campos personalizados</strong><span>{snapshot.customFields.length}</span></div></header><div>{snapshot.customFields.map(field=>{const current=value(field.id);if(field.type==='multi'){const selected=Array.isArray(current)?current:[];return <fieldset key={field.id}><legend>{field.name}</legend>{field.options.map(option=><label key={option.id}><input type="checkbox" checked={selected.includes(option.id)} onChange={()=>save(field.id,selected.includes(option.id)?selected.filter(id=>id!==option.id):[...selected,option.id])}/><i style={{background:option.color}}/>{option.label}</label>)}</fieldset>}if(field.type==='single')return <label key={field.id}>{field.name}<select value={typeof current==='string'?current:''} onChange={e=>save(field.id,e.target.value||null)}><option value="">Não definido</option>{field.options.map(option=><option key={option.id} value={option.id}>{option.label}</option>)}</select></label>;return <label key={field.id}>{field.name}<input type={field.type} defaultValue={current==null?'':String(current)} onBlur={e=>save(field.id,e.target.value?field.type==='number'?Number(e.target.value):e.target.value:null)}/></label>})}</div></section>}

function WebTaskExtras({snapshot,task,onRefresh,onOpen}:{snapshot:WorkspaceSnapshot;task:Task;onRefresh:()=>Promise<void>;onOpen:(task:Task)=>void}){
  const [checklistTitle,setChecklistTitle]=useState(''),[subtaskTitle,setSubtaskTitle]=useState(''),[dependencyId,setDependencyId]=useState(''),[comment,setComment]=useState(''),[attachment,setAttachment]=useState({name:'',url:''}),[tab,setTab]=useState<'comments'|'activity'>('comments')
  const checklist=snapshot.checklistItems.filter(item=>item.taskId===task.id).sort((a,b)=>a.position-b.position)
  const subtasks=snapshot.tasks.filter(item=>item.parentId===task.id)
  const dependencies=snapshot.dependencies.filter(item=>item.taskId===task.id)
  const dependencyTasks=dependencies.map(item=>snapshot.tasks.find(candidate=>candidate.id===item.dependsOnTaskId)).filter((item):item is Task=>Boolean(item))
  const candidates=snapshot.tasks.filter(item=>!item.parentId&&item.projectId===task.projectId&&item.id!==task.id&&!dependencies.some(dependency=>dependency.dependsOnTaskId===item.id))
  const comments=snapshot.comments.filter(item=>item.taskId===task.id),attachments=snapshot.attachments.filter(item=>item.taskId===task.id),activities=snapshot.activities.filter(item=>item.taskId===task.id)
  const doneStatus=snapshot.statuses.at(-1)?.id,firstStatus=snapshot.statuses[0]?.id
  const actionLabel=(action:string)=>({created:'criou esta tarefa',subtask_created:'criou uma subtarefa',updated:'atualizou a tarefa',commented:'comentou',attachment_added:'adicionou um anexo',checklist_added:'adicionou um item ao checklist',checklist_completed:'concluiu um item do checklist',checklist_updated:'atualizou o checklist',dependency_added:'adicionou um bloqueio',custom_field_updated:'atualizou um campo personalizado'}[action]??action)
  const formatDate=(value:string)=>new Intl.DateTimeFormat('pt-BR',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'}).format(new Date(value))
  return <div className="web-task-extras">
    <WebTaskCustomFields snapshot={snapshot} task={task} onRefresh={onRefresh}/>
    <section><header><div><CheckSquare2/><strong>Checklist</strong><span>{checklist.filter(item=>item.completed).length}/{checklist.length}</span></div></header><div className="web-checklist">{checklist.map(item=><div key={item.id}><button type="button" className={item.completed?'done':''} onClick={async()=>{await api(`/checklist/${item.id}`,{method:'PATCH',body:JSON.stringify({completed:!item.completed})});await onRefresh()}}>{item.completed?<CheckCircle2/>:<Circle/>}{item.title}</button><button type="button" onClick={async()=>{await api(`/checklist/${item.id}`,{method:'DELETE'});await onRefresh()}}><Trash2/></button></div>)}</div><div className="web-inline-create"><input value={checklistTitle} onChange={e=>setChecklistTitle(e.target.value)} placeholder="Novo item do checklist"/><button type="button" onClick={async()=>{if(!checklistTitle.trim())return;await api(`/tasks/${task.id}/checklist`,{method:'POST',body:JSON.stringify({title:checklistTitle})});setChecklistTitle('');await onRefresh()}}>Adicionar</button></div></section>
    <section><header><div><Link2/><strong>Dependências</strong><span>{dependencyTasks.length}</span></div></header><p className="web-section-help">Bloqueada pelas tarefas abaixo:</p>{dependencyTasks.map(item=><div className="web-dependency" key={item.id}><button type="button" onClick={()=>onOpen(item)}>{item.title}<small>{snapshot.statuses.find(status=>status.id===item.statusId)?.name}</small></button><button type="button" onClick={async()=>{await api(`/tasks/${task.id}/dependencies/${item.id}`,{method:'DELETE'});await onRefresh()}}><X/></button></div>)}<div className="web-inline-create"><select value={dependencyId} onChange={e=>setDependencyId(e.target.value)}><option value="">Selecionar tarefa...</option>{candidates.map(item=><option value={item.id} key={item.id}>{item.title}</option>)}</select><button type="button" onClick={async()=>{if(!dependencyId)return;await api(`/tasks/${task.id}/dependencies`,{method:'POST',body:JSON.stringify({dependsOnTaskId:dependencyId})});setDependencyId('');await onRefresh()}}>Adicionar</button></div></section>
    <section><header><div><CheckCircle2/><strong>Subtarefas</strong><span>{subtasks.filter(item=>item.statusId===doneStatus).length}/{subtasks.length}</span></div></header><div className="web-subtasks">{subtasks.map(item=>{const done=item.statusId===doneStatus;return <div key={item.id}><button type="button" onClick={async()=>{await api(`/tasks/${item.id}`,{method:'PATCH',body:JSON.stringify({statusId:done?firstStatus:doneStatus})});await onRefresh()}}>{done?<CheckCircle2/>:<Circle/>}</button><button type="button" onClick={()=>onOpen(item)}>{item.title}<small>{snapshot.statuses.find(status=>status.id===item.statusId)?.name}</small></button></div>})}</div><div className="web-inline-create"><input value={subtaskTitle} onChange={e=>setSubtaskTitle(e.target.value)} placeholder="Adicionar subtarefa"/><button type="button" onClick={async()=>{if(!subtaskTitle.trim()||!firstStatus)return;await api('/tasks',{method:'POST',body:JSON.stringify({projectId:task.projectId,statusId:firstStatus,title:subtaskTitle,parentId:task.id})});setSubtaskTitle('');await onRefresh()}}>Adicionar</button></div></section>
    <section><header><div><Paperclip/><strong>Anexos e links</strong><span>{attachments.length}</span></div></header><div className="web-attachments">{attachments.map(item=><div key={item.id}><Link2/><a href={item.url} target="_blank" rel="noreferrer"><strong>{item.name}</strong><small>{item.url}</small></a><ExternalLink/><button type="button" onClick={async()=>{await api(`/attachments/${item.id}`,{method:'DELETE'});await onRefresh()}}><X/></button></div>)}</div><div className="web-attachment-create"><input value={attachment.name} onChange={e=>setAttachment({...attachment,name:e.target.value})} placeholder="Nome"/><input value={attachment.url} onChange={e=>setAttachment({...attachment,url:e.target.value})} placeholder="https://..."/><button type="button" onClick={async()=>{if(!attachment.name.trim()||!attachment.url.trim())return;await api(`/tasks/${task.id}/attachments`,{method:'POST',body:JSON.stringify(attachment)});setAttachment({name:'',url:''});await onRefresh()}}>Vincular</button></div></section>
    <section className="web-conversation"><nav><button type="button" className={tab==='comments'?'active':''} onClick={()=>setTab('comments')}><MessageSquare/>Comentários <span>{comments.length}</span></button><button type="button" className={tab==='activity'?'active':''} onClick={()=>setTab('activity')}>Histórico <span>{activities.length}</span></button></nav>{tab==='comments'?<><div className="web-comments">{comments.map(item=><article key={item.id}><b>{item.authorName.slice(0,2).toUpperCase()}</b><div><header><strong>{item.authorName}</strong><small>{formatDate(item.createdAt)}</small></header><p>{item.body}</p></div></article>)}</div><div className="web-mentions">Mencionar:{snapshot.members.filter(member=>member.userId!==snapshot.user.id).map(member=><button type="button" key={member.userId} onClick={()=>setComment(value=>`${value}${value&&!value.endsWith(' ')?' ':''}@${member.name} `)}>@{member.name}</button>)}</div><div className="web-comment-create"><textarea value={comment} onChange={e=>setComment(e.target.value)} placeholder="Comente e use @ para mencionar alguém..."/><button type="button" onClick={async()=>{if(!comment.trim())return;await api(`/tasks/${task.id}/comments`,{method:'POST',body:JSON.stringify({body:comment})});setComment('');await onRefresh()}}><Send/></button></div></>:<div className="web-activity">{activities.map(item=><article key={item.id}><i/><p><strong>{item.authorName??'Orbitask'}</strong> {actionLabel(item.action)}<small>{formatDate(item.createdAt)}</small></p></article>)}</div>}</section>
  </div>
}

function WebCustomFieldSummary({snapshot,task}:{snapshot:WorkspaceSnapshot;task:Task}){const entries=snapshot.customFields.map(field=>({field,value:snapshot.customFieldValues.find(item=>item.taskId===task.id&&item.fieldId===field.id)?.value})).filter(item=>item.value!==null&&item.value!==undefined&&item.value!=='').slice(0,2);const display=(field:CustomFieldDefinition,value:string|number|string[])=>Array.isArray(value)?value.map(id=>field.options.find(option=>option.id===id)?.label??id).join(', '):field.type==='single'?field.options.find(option=>option.id===value)?.label??String(value):String(value);return entries.length?<div className="web-custom-summary">{entries.map(({field,value})=><span key={field.id}><small>{field.name}</small>{display(field,value as string|number|string[])}</span>)}</div>:null}

const isoDate=(date:Date)=>`${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`
const addDays=(date:Date,days:number)=>{const next=new Date(date);next.setDate(next.getDate()+days);return next}
function WebCalendarView({snapshot,tasks,onOpen,onRefresh}:{snapshot:WorkspaceSnapshot;tasks:Task[];onOpen:(task:Task)=>void;onRefresh:()=>Promise<void>}){const [cursor,setCursor]=useState(()=>new Date()),[mode,setMode]=useState<'month'|'week'>('month');const today=isoDate(new Date());const start=mode==='month'?new Date(cursor.getFullYear(),cursor.getMonth(),1):addDays(cursor,-((cursor.getDay()+6)%7));if(mode==='month')start.setDate(start.getDate()-((start.getDay()+6)%7));const days=Array.from({length:mode==='month'?42:7},(_,i)=>addDays(start,i));const dated=tasks.filter(task=>!task.parentId&&task.dueDate),undated=tasks.filter(task=>!task.parentId&&!task.dueDate);const move=async(taskId:string,dueDate:string)=>{await api(`/tasks/${taskId}`,{method:'PATCH',body:JSON.stringify({dueDate})});await onRefresh()};return <section className="web-calendar-view"><header><div><button onClick={()=>setCursor(addDays(cursor,mode==='week'?-7:-30))}>‹</button><button onClick={()=>setCursor(new Date())}>Hoje</button><button onClick={()=>setCursor(addDays(cursor,mode==='week'?7:30))}>›</button><h2>{cursor.toLocaleDateString('pt-BR',{month:'long',year:'numeric'})}</h2></div><nav><button className={mode==='month'?'active':''} onClick={()=>setMode('month')}>Mês</button><button className={mode==='week'?'active':''} onClick={()=>setMode('week')}>Semana</button></nav></header><div className={`web-calendar-grid ${mode}`}>{days.map(day=>{const key=isoDate(day),items=dated.filter(task=>task.dueDate===key);return <article className={`${key===today?'today':''} ${day.getMonth()!==cursor.getMonth()&&mode==='month'?'muted':''}`} key={key} onDragOver={e=>e.preventDefault()} onDrop={e=>move(e.dataTransfer.getData('text/task-id'),key)}><header><span>{day.toLocaleDateString('pt-BR',{weekday:'short'})}</span><strong>{day.getDate()}</strong></header>{items.map(task=><button draggable onDragStart={e=>e.dataTransfer.setData('text/task-id',task.id)} key={task.id} style={{'--task-color':snapshot.statuses.find(status=>status.id===task.statusId)?.color} as React.CSSProperties} onClick={()=>onOpen(task)}>{task.title}</button>)}</article>})}</div>{undated.length>0&&<aside><strong>Sem prazo</strong><p>Arraste uma tarefa para o calendário.</p><div>{undated.map(task=><button draggable onDragStart={e=>e.dataTransfer.setData('text/task-id',task.id)} key={task.id} onClick={()=>onOpen(task)}>{task.title}</button>)}</div></aside>}</section>}
function WebTimelineView({snapshot,tasks,onOpen}:{snapshot:WorkspaceSnapshot;tasks:Task[];onOpen:(task:Task)=>void}){const ranged=tasks.filter(task=>!task.parentId&&(task.startDate||task.dueDate));const start=ranged.length?new Date([...ranged].sort((a,b)=>(a.startDate??a.dueDate??'').localeCompare(b.startDate??b.dueDate??''))[0].startDate??ranged[0].dueDate!):new Date();const days=Array.from({length:30},(_,i)=>addDays(start,i));return <section className="web-timeline-view"><header><div><small>CRONOGRAMA</small><h2>Timeline do projeto</h2></div><span>{days[0].toLocaleDateString('pt-BR',{day:'2-digit',month:'short'})} — {days.at(-1)?.toLocaleDateString('pt-BR',{day:'2-digit',month:'short'})}</span></header><div className="web-timeline"><div className="timeline-dates"><span>Tarefa</span>{days.map(day=><small key={isoDate(day)}>{day.getDate()}<b>{day.toLocaleDateString('pt-BR',{weekday:'narrow'})}</b></small>)}</div>{ranged.map(task=>{const from=new Date(`${task.startDate??task.dueDate}T12:00:00`),to=new Date(`${task.dueDate??task.startDate}T12:00:00`),offset=Math.max(0,Math.floor((from.getTime()-start.getTime())/86400000)),span=Math.max(1,Math.floor((to.getTime()-from.getTime())/86400000)+1),status=snapshot.statuses.find(item=>item.id===task.statusId);return <div className="timeline-row" key={task.id}><button onClick={()=>onOpen(task)}>{task.title}<small>{status?.name}</small></button><div className="timeline-track"><i style={{left:`${offset/30*100}%`,width:`${Math.min(span,30-offset)/30*100}%`,background:status?.color}} onClick={()=>onOpen(task)}>{span>2&&task.title}</i>{snapshot.dependencies.filter(dep=>dep.taskId===task.id).map(dep=><span key={dep.dependsOnTaskId} title="Possui dependência">↳</span>)}</div></div>})}{!ranged.length&&<div className="timeline-empty"><CalendarDays/><strong>Nenhuma tarefa programada</strong><p>Adicione início ou término às tarefas para montar o cronograma.</p></div>}</div></section>}

function WebAutomationsPage({snapshot,onBack}:{snapshot:WorkspaceSnapshot;onBack:()=>void}){
  const empty=():SaveAutomationInput=>({projectId:snapshot.project.id,name:'',enabled:true,trigger:'status_changed',triggerValue:snapshot.statuses.at(-1)?.id??'',actions:[{id:crypto.randomUUID(),type:'set_priority',value:snapshot.settings.priorities[0]?.id??''}]})
  const [items,setItems]=useState<ProjectAutomation[]>([]),[runs,setRuns]=useState<AutomationRun[]>([]),[draft,setDraft]=useState<SaveAutomationInput|null>(null),[busy,setBusy]=useState(false),[error,setError]=useState(''),[removeId,setRemoveId]=useState<string|null>(null)
  const load=async()=>{const data=await api<{automations:ProjectAutomation[];runs:AutomationRun[]}>(`/automations?projectId=${snapshot.project.id}`);setItems(data.automations);setRuns(data.runs)}
  useEffect(()=>{load()},[snapshot.project.id])
  const actionLabels:Record<AutomationActionType,string>={set_status:'Alterar status',set_priority:'Alterar prioridade',assign_user:'Atribuir pessoa',add_tag:'Adicionar tag',set_due_days:'Definir prazo em dias',create_subtask:'Criar subtarefa'}
  const options=(type:AutomationActionType)=>type==='set_status'?snapshot.statuses:type==='set_priority'?snapshot.settings.priorities:type==='assign_user'?snapshot.members.map(member=>({id:member.userId,name:member.name})):type==='add_tag'?snapshot.settings.tags:[]
  const save=async()=>{if(!draft||!draft.name.trim()||!draft.actions.length)return;setBusy(true);setError('');try{await api('/automations',{method:'POST',body:JSON.stringify(draft)});setDraft(null);await load()}catch(e){setError(e instanceof Error?e.message:'Não foi possível salvar a automação')}finally{setBusy(false)}}
  const remove=async(id:string)=>{if(removeId!==id){setRemoveId(id);return}await api(`/automations/${id}`,{method:'DELETE'});setRemoveId(null);await load()}
  return <section className="web-automations-page"><header><button onClick={onBack}><ArrowRight/> Voltar ao projeto</button><div><small>CONFIGURAÇÕES DO PROJETO</small><h1>Automações</h1><p>Crie regras para manter o trabalho fluindo sem tarefas repetitivas.</p></div><button className="web-automation-primary" onClick={()=>setDraft(empty())}><Plus/> Nova automação</button></header><div className="web-automation-layout"><section><header><h2>Regras do projeto</h2><span>{items.length}</span></header>{items.map(item=><article key={item.id}><i className={item.enabled?'enabled':''}><Zap/></i><button onClick={()=>setDraft({...item})}><strong>{item.name}</strong><small>{item.trigger==='task_created'?'Quando uma tarefa for criada':'Quando o status mudar'} · {item.actions.length} ação(ões)</small></button><button className={removeId===item.id?'confirm':''} onClick={()=>remove(item.id)}>{removeId===item.id?'Confirmar':<Trash2/>}</button></article>)}{!items.length&&<div className="web-automation-empty"><Zap/><h3>Automatize o trabalho repetitivo</h3><p>Escolha um gatilho e as ações que o Orbitask deve executar.</p><button onClick={()=>setDraft(empty())}>Criar primeira automação</button></div>}</section><aside><header><h2>Execuções recentes</h2></header>{runs.slice(0,10).map(run=><article key={run.id}><i className={run.status}/><div><strong>{run.status==='success'?'Executada com sucesso':'Falha na execução'}</strong><small>{run.message}</small></div><time>{new Date(run.createdAt).toLocaleDateString('pt-BR')}</time></article>)}{!runs.length&&<p>O histórico aparecerá depois da primeira execução.</p>}</aside></div>{error&&<div className="web-error">{error}</div>}{draft&&<div className="web-automation-backdrop" onMouseDown={e=>e.target===e.currentTarget&&setDraft(null)}><div className="web-automation-builder"><header><span><Zap/></span><div><small>AUTOMAÇÃO DO PROJETO</small><h2>{draft.id?'Editar regra':'Nova regra'}</h2></div><button onClick={()=>setDraft(null)}><X/></button></header><label>Nome da regra<input autoFocus value={draft.name} onChange={e=>setDraft({...draft,name:e.target.value})} placeholder="Ex.: Preparar tarefa concluída"/></label><div className="web-automation-step"><b>QUANDO</b><select value={draft.trigger} onChange={e=>setDraft({...draft,trigger:e.target.value as SaveAutomationInput['trigger'],triggerValue:e.target.value==='status_changed'?snapshot.statuses[0]?.id:null})}><option value="status_changed">O status mudar para</option><option value="task_created">Uma tarefa for criada</option></select>{draft.trigger==='status_changed'&&<select value={draft.triggerValue??''} onChange={e=>setDraft({...draft,triggerValue:e.target.value})}>{snapshot.statuses.map(item=><option key={item.id} value={item.id}>{item.name}</option>)}</select>}</div>{draft.actions.map((action,index)=>{const choices=options(action.type);return <div className="web-automation-step" key={action.id}><b>ENTÃO</b><select value={action.type} onChange={e=>{const type=e.target.value as AutomationActionType;setDraft({...draft,actions:draft.actions.map((item,i)=>i===index?{...item,type,value:options(type)[0]?.id??(type==='set_due_days'?'1':'')}:item)})}}>{Object.entries(actionLabels).map(([value,label])=><option value={value} key={value}>{label}</option>)}</select>{choices.length?<select value={action.value} onChange={e=>setDraft({...draft,actions:draft.actions.map((item,i)=>i===index?{...item,value:e.target.value}:item)})}>{choices.map(item=><option value={item.id} key={item.id}>{item.name}</option>)}</select>:<input type={action.type==='set_due_days'?'number':'text'} min={action.type==='set_due_days'?0:undefined} value={action.value} onChange={e=>setDraft({...draft,actions:draft.actions.map((item,i)=>i===index?{...item,value:e.target.value}:item)})} placeholder={action.type==='create_subtask'?'Título da subtarefa':'Dias após o gatilho'}/>}<button onClick={()=>setDraft({...draft,actions:draft.actions.filter((_,i)=>i!==index)})}><Trash2/></button></div>})}<button className="web-add-automation-action" onClick={()=>setDraft({...draft,actions:[...draft.actions,{id:crypto.randomUUID(),type:'set_priority',value:snapshot.settings.priorities[0]?.id??''}]})}><Plus/> Adicionar ação</button><footer><label><input type="checkbox" checked={draft.enabled} onChange={e=>setDraft({...draft,enabled:e.target.checked})}/> Regra ativa</label><div><button onClick={()=>setDraft(null)}>Cancelar</button><button className="web-automation-primary" disabled={busy||!draft.name.trim()||!draft.actions.length} onClick={save}>{busy?'Salvando...':'Salvar automação'}</button></div></footer></div></div>}</section>
}

const emptyAdvancedFilter=():AdvancedTaskFilter=>({query:'',statusIds:[],priorityIds:[],assigneeIds:[],due:'all',sort:'position',direction:'asc',group:'status'})
const activeFilterCount=(filter:AdvancedTaskFilter)=>filter.statusIds.length+filter.priorityIds.length+filter.assigneeIds.length+(filter.due==='all'?0:1)+(filter.sort==='position'&&filter.group==='status'?0:1)
function applyAdvancedFilters(tasks:Task[],filter:AdvancedTaskFilter,snapshot:WorkspaceSnapshot){
  const now=new Date();now.setHours(0,0,0,0);const week=new Date(now);week.setDate(week.getDate()+7)
  const result=tasks.filter(task=>{
    const due=task.dueDate?new Date(`${task.dueDate}T12:00:00`):null
    return(!filter.query||`${task.title} ${task.description}`.toLowerCase().includes(filter.query.toLowerCase()))&&(!filter.statusIds.length||filter.statusIds.includes(task.statusId))&&(!filter.priorityIds.length||filter.priorityIds.includes(task.priority))&&(!filter.assigneeIds.length||task.assigneeIds.some(id=>filter.assigneeIds.includes(id)))&&(filter.due==='all'||(filter.due==='no_due'&&!due)||(filter.due==='overdue'&&due&&due<now)||(filter.due==='today'&&due&&due.toDateString()===now.toDateString())||(filter.due==='week'&&due&&due>=now&&due<=week))
  })
  const priorityPosition=(id:string)=>snapshot.settings.priorities.find(item=>item.id===id)?.position??999
  return result.sort((a,b)=>{let value=0;if(filter.sort==='title')value=a.title.localeCompare(b.title,'pt-BR');else if(filter.sort==='due_date')value=(a.dueDate??'9999').localeCompare(b.dueDate??'9999');else if(filter.sort==='priority')value=priorityPosition(a.priority)-priorityPosition(b.priority);else if(filter.sort==='updated_at')value=a.updatedAt.localeCompare(b.updatedAt);else value=a.position-b.position;return filter.direction==='desc'?-value:value})
}

function WebAdvancedFilters({snapshot,value,onChange,onClose}:{snapshot:WorkspaceSnapshot;value:AdvancedTaskFilter;onChange:(value:AdvancedTaskFilter)=>void;onClose:()=>void}){
  const [saved,setSaved]=useState<SavedTaskFilter[]>([]),[name,setName]=useState(''),[busy,setBusy]=useState(false)
  const load=()=>api<SavedTaskFilter[]>(`/saved-filters?projectId=${snapshot.project.id}`).then(setSaved)
  useEffect(()=>{load()},[snapshot.project.id])
  const toggle=(key:'statusIds'|'priorityIds'|'assigneeIds',id:string)=>onChange({...value,[key]:value[key].includes(id)?value[key].filter(item=>item!==id):[...value[key],id]})
  const save=async()=>{if(!name.trim())return;setBusy(true);await api('/saved-filters',{method:'POST',body:JSON.stringify({projectId:snapshot.project.id,name,filter:value})});setName('');await load();setBusy(false)}
  return <div className="web-advanced-filter" onPointerDown={event=>event.stopPropagation()}><header><div><span><Filter/></span><div><strong>Refinar tarefas</strong><small>Combine critérios e salve sua visão</small></div></div><button onClick={onClose}><X/></button></header><div className="web-filter-scroll"><section><h4>Status</h4><div className="web-filter-chips">{snapshot.statuses.map(item=><button className={value.statusIds.includes(item.id)?'selected':''} key={item.id} onClick={()=>toggle('statusIds',item.id)}><i style={{background:item.color}}/>{item.name}</button>)}</div></section><section><h4>Prioridade</h4><div className="web-filter-chips">{snapshot.settings.priorities.map(item=><button className={value.priorityIds.includes(item.id)?'selected':''} key={item.id} onClick={()=>toggle('priorityIds',item.id)}><i style={{background:item.color}}/>{item.name}</button>)}</div></section><section><h4>Responsável</h4><div className="web-filter-chips">{snapshot.members.map(item=><button className={value.assigneeIds.includes(item.userId)?'selected':''} key={item.userId} onClick={()=>toggle('assigneeIds',item.userId)}>{item.name}</button>)}</div></section><div className="web-filter-grid"><label>Prazo<select value={value.due} onChange={e=>onChange({...value,due:e.target.value as AdvancedTaskFilter['due']})}><option value="all">Qualquer prazo</option><option value="overdue">Atrasadas</option><option value="today">Vencem hoje</option><option value="week">Próximos 7 dias</option><option value="no_due">Sem prazo</option></select></label><label>Ordenar por<select value={value.sort} onChange={e=>onChange({...value,sort:e.target.value as AdvancedTaskFilter['sort']})}><option value="position">Ordem do quadro</option><option value="title">Título</option><option value="due_date">Prazo</option><option value="priority">Prioridade</option><option value="updated_at">Atualização</option></select></label><label>Agrupar por<select value={value.group} onChange={e=>onChange({...value,group:e.target.value as AdvancedTaskFilter['group']})}><option value="status">Status</option><option value="priority">Prioridade</option><option value="assignee">Responsável</option><option value="none">Sem agrupamento</option></select></label><button className="web-sort-direction" onClick={()=>onChange({...value,direction:value.direction==='asc'?'desc':'asc'})}><ArrowUpDown/> {value.direction==='asc'?'Crescente':'Decrescente'}</button></div><section className="web-saved-filters"><h4><Bookmark/> Filtros salvos</h4>{saved.map(item=><div key={item.id}><button onClick={()=>onChange(item.filter)}><strong>{item.name}</strong><small>Aplicar combinação</small></button><button aria-label={`Excluir ${item.name}`} onClick={async()=>{await api(`/saved-filters/${item.id}`,{method:'DELETE'});await load()}}><Trash2/></button></div>)}<div className="web-save-filter"><input value={name} onChange={e=>setName(e.target.value)} placeholder="Nome desta visão"/><button disabled={busy||!name.trim()} onClick={save}>{busy?'Salvando...':'Salvar'}</button></div></section></div><footer><button onClick={()=>onChange(emptyAdvancedFilter())}>Limpar tudo</button><button className="web-filter-done" onClick={onClose}>Ver tarefas</button></footer></div>
}

function WebFilteredList({snapshot,tasks,group,onOpen}:{snapshot:WorkspaceSnapshot;tasks:Task[];group:AdvancedTaskFilter['group'];onOpen:(task:Task)=>void}){
  const roots=tasks.filter(task=>!task.parentId),groups=new Map<string,Task[]>()
  roots.forEach(task=>{const keys=group==='none'?['Todas as tarefas']:group==='status'?[snapshot.statuses.find(item=>item.id===task.statusId)?.name??'Sem status']:group==='priority'?[snapshot.settings.priorities.find(item=>item.id===task.priority)?.name??'Sem prioridade']:(task.assigneeIds.length?task.assigneeIds.map(id=>snapshot.members.find(item=>item.userId===id)?.name??'Pessoa removida'):['Sem responsável']);keys.forEach(key=>groups.set(key,[...(groups.get(key)??[]),task]))})
  return <section className="web-list grouped"><header><span>Tarefa</span><span>Status</span><span>Prioridade</span><span>Prazo</span></header>{[...groups].map(([label,items])=><div className="web-list-group" key={label}><h3>{label}<span>{items.length}</span></h3>{items.map(task=>{const status=snapshot.statuses.find(item=>item.id===task.statusId),priority=snapshot.settings.priorities.find(item=>item.id===task.priority);return <button key={task.id} onClick={()=>onOpen(task)}><strong>{task.title}<WebCustomFieldSummary snapshot={snapshot} task={task}/></strong><span><i style={{background:status?.color}}/>{status?.name}</span><span style={{color:priority?.color}}>{priority?.name??task.priority}</span><span>{task.dueDate?new Date(`${task.dueDate}T12:00:00`).toLocaleDateString('pt-BR'):'Sem prazo'}</span></button>})}</div>)}</section>
}

function WebAppPage(){
  const [session,setSession]=useState<AuthSession|null>(null)
  const [snapshot,setSnapshot]=useState<WorkspaceSnapshot|null>(null)
  const [mode,setMode]=useState<'login'|'signup'>(new URLSearchParams(location.search).has('cadastro')?'signup':'login')
  const [form,setForm]=useState({name:'',workspaceName:'',email:'',password:''})
  const [error,setError]=useState('')
  const [busy,setBusy]=useState(false)
  const [query,setQuery]=useState('')
  const [searchOpen,setSearchOpen]=useState(false)
  const [searchResult,setSearchResult]=useState<GlobalSearchResult>({tasks:[],projects:[],people:[],recent:[]})
  const searchRef=useRef<HTMLLabelElement>(null)
  const [createOpen,setCreateOpen]=useState(false)
  const [customFieldsOpen,setCustomFieldsOpen]=useState(false)
  const [filtersOpen,setFiltersOpen]=useState(false)
  const filterRef=useRef<HTMLSpanElement>(null)
  const [customFilter,setCustomFilter]=useState({fieldId:'',value:''})
  const [advancedFilter,setAdvancedFilter]=useState<AdvancedTaskFilter>(emptyAdvancedFilter)
  const [selectedTask,setSelectedTask]=useState<Task|null>(null)
  const [taskForm,setTaskForm]=useState({title:'',description:'',statusId:'',priority:'medium' as Priority,startDate:'',dueDate:'',assigneeIds:[] as string[],primaryAssigneeId:'' as string,followerIds:[] as string[]})
  const [view,setView]=useState<'board'|'list'|'calendar'|'timeline'>('board')
  const [page,setPage]=useState<'project'|'reports'|'portfolios'|'team'|'inbox'|'automations'>('project')
  const inviteToken=new URLSearchParams(location.search).get('convite')
  const [inviteInfo,setInviteInfo]=useState<{email:string;role:WorkspaceRole;workspaceName:string;invitedByName:string}|null>(null)
  const [inviteForm,setInviteForm]=useState({name:'',password:''})

  const loadSnapshot=async(projectId?:string)=>{const raw=await api<WorkspaceSnapshot>(`/workspace/snapshot${projectId?`?projectId=${projectId}`:''}`);const next={...raw,members:raw.members??[],invites:raw.invites??[],checklistItems:raw.checklistItems??[],dependencies:raw.dependencies??[],customFields:raw.customFields??[],customFieldValues:raw.customFieldValues??[],tasks:raw.tasks.map(task=>({...task,assigneeIds:task.assigneeIds??[],primaryAssigneeId:task.primaryAssigneeId??null,followerIds:task.followerIds??[]}))};setSnapshot(next);setSelectedTask(current=>current?next.tasks.find(task=>task.id===current.id)??null:null);setView(next.preferences.defaultView);return next}

  useEffect(()=>{
    if(inviteToken){api<typeof inviteInfo>(`/invites/${inviteToken}`).then(setInviteInfo).catch(e=>setError(e instanceof Error?e.message:'Convite inválido'));return}
    if(localStorage.getItem('orbitask_token'))api<AuthSession>('/auth/me')
      .then(s=>{setSession(s);return loadSnapshot()})
      .catch(()=>localStorage.removeItem('orbitask_token'))
  },[inviteToken])

  useEffect(()=>{if(!filtersOpen)return;const close=(event:PointerEvent)=>{if(!filterRef.current?.contains(event.target as Node))setFiltersOpen(false)};const escape=(event:KeyboardEvent)=>{if(event.key==='Escape')setFiltersOpen(false)};document.addEventListener('pointerdown',close);document.addEventListener('keydown',escape);return()=>{document.removeEventListener('pointerdown',close);document.removeEventListener('keydown',escape)}},[filtersOpen])
  useEffect(()=>{if(!session||!searchOpen)return;const timer=setTimeout(()=>api<GlobalSearchResult>(`/search?q=${encodeURIComponent(query)}`).then(setSearchResult).catch(()=>{}),220);return()=>clearTimeout(timer)},[query,searchOpen,session])
  useEffect(()=>{const shortcut=(event:KeyboardEvent)=>{if((event.metaKey||event.ctrlKey)&&event.key.toLowerCase()==='k'){event.preventDefault();setSearchOpen(true);searchRef.current?.querySelector('input')?.focus()}if(event.key==='Escape')setSearchOpen(false)};document.addEventListener('keydown',shortcut);return()=>document.removeEventListener('keydown',shortcut)},[])
  useEffect(()=>{if(!searchOpen)return;const outside=(event:PointerEvent)=>{if(!searchRef.current?.contains(event.target as Node))setSearchOpen(false)};document.addEventListener('pointerdown',outside);return()=>document.removeEventListener('pointerdown',outside)},[searchOpen])

  const acceptInvite=async(e:FormEvent)=>{e.preventDefault();if(!inviteToken)return;setBusy(true);setError('');try{const result=await api<{token:string;session:AuthSession}>(`/invites/${inviteToken}/accept`,{method:'POST',body:JSON.stringify(inviteForm)});localStorage.setItem('orbitask_token',result.token);setSession(result.session);history.replaceState({},'',location.pathname);await loadSnapshot()}catch(e){setError(e instanceof Error?e.message:'Não foi possível aceitar o convite')}finally{setBusy(false)}}

  const submit=async(e:FormEvent)=>{
    e.preventDefault();setBusy(true);setError('')
    try{
      const result=await api<{token:string;session:AuthSession}>(`/auth/${mode==='login'?'login':'signup'}`,{method:'POST',body:JSON.stringify(form)})
      localStorage.setItem('orbitask_token',result.token);setSession(result.session);await loadSnapshot()
    }catch(e){setError(e instanceof Error?e.message:'Erro inesperado')}finally{setBusy(false)}
  }

  const openCreate=(statusId?:string)=>{
    if(!snapshot)return
    setTaskForm({title:'',description:'',statusId:statusId??snapshot.statuses[0]?.id??'',priority:snapshot.settings.priorities[0]?.id??'medium',startDate:'',dueDate:'',assigneeIds:[session?.user.id??''].filter(Boolean),primaryAssigneeId:session?.user.id??'',followerIds:[session?.user.id??''].filter(Boolean)})
    setCreateOpen(true)
  }

  const createTask=async(e:FormEvent)=>{
    e.preventDefault();if(!snapshot||!taskForm.title.trim())return
    setBusy(true);setError('')
    try{
      const task=await api<Task>('/tasks',{method:'POST',body:JSON.stringify({projectId:snapshot.project.id,statusId:taskForm.statusId,title:taskForm.title,priority:taskForm.priority})})
      await api(`/tasks/${task.id}`,{method:'PATCH',body:JSON.stringify({description:taskForm.description,startDate:taskForm.startDate||null,dueDate:taskForm.dueDate||null,assigneeIds:taskForm.assigneeIds,primaryAssigneeId:taskForm.primaryAssigneeId||null,followerIds:taskForm.followerIds})})
      await loadSnapshot(snapshot.project.id);setCreateOpen(false)
    }catch(e){setError(e instanceof Error?e.message:'Não foi possível criar a tarefa')}finally{setBusy(false)}
  }

  const updateTask=async(e:FormEvent)=>{
    e.preventDefault();if(!snapshot||!selectedTask)return
    setBusy(true);setError('')
    try{
      await api(`/tasks/${selectedTask.id}`,{method:'PATCH',body:JSON.stringify({title:taskForm.title,description:taskForm.description,statusId:taskForm.statusId,priority:taskForm.priority,startDate:taskForm.startDate||null,dueDate:taskForm.dueDate||null,assigneeIds:taskForm.assigneeIds,primaryAssigneeId:taskForm.primaryAssigneeId||null,followerIds:taskForm.followerIds})})
      await loadSnapshot(snapshot.project.id);setSelectedTask(null)
    }catch(e){setError(e instanceof Error?e.message:'Não foi possível atualizar a tarefa')}finally{setBusy(false)}
  }

  const openTask=(task:Task)=>{setSelectedTask(task);setTaskForm({title:task.title,description:task.description,statusId:task.statusId,priority:task.priority,startDate:task.startDate??'',dueDate:task.dueDate??'',assigneeIds:task.assigneeIds??[],primaryAssigneeId:task.primaryAssigneeId??'',followerIds:task.followerIds??[]})}
  const changeView=async(next:'board'|'list')=>{if(!snapshot)return;setView(next);const preferences=await api<WorkspaceSnapshot['preferences']>(`/projects/${snapshot.project.id}/preferences`,{method:'PATCH',body:JSON.stringify({defaultView:next})});setSnapshot({...snapshot,preferences})}
  const toggleDensity=async()=>{if(!snapshot)return;const density=snapshot.preferences.cardDensity==='compact'?'detailed':'compact';const preferences=await api<WorkspaceSnapshot['preferences']>(`/projects/${snapshot.project.id}/preferences`,{method:'PATCH',body:JSON.stringify({cardDensity:density})});setSnapshot({...snapshot,preferences})}
  const moveTask=async(taskId:string,statusId:string)=>{if(!snapshot)return;setSnapshot({...snapshot,tasks:snapshot.tasks.map(task=>task.id===taskId?{...task,statusId}:task)});await api(`/tasks/${taskId}`,{method:'PATCH',body:JSON.stringify({statusId,position:Date.now()})});await loadSnapshot(snapshot.project.id)}
  const signOut=()=>{localStorage.removeItem('orbitask_token');setSession(null);setSnapshot(null)}

  if(session&&snapshot){
    const tasks=applyAdvancedFilters(snapshot.tasks,{...advancedFilter,query:''},snapshot).filter(task=>(!customFilter.fieldId||String(snapshot.customFieldValues.find(item=>item.taskId===task.id&&item.fieldId===customFilter.fieldId)?.value??'').toLowerCase().includes(customFilter.value.toLowerCase())))
    const initials=session.user.name.split(' ').map(part=>part[0]).slice(0,2).join('').toUpperCase()
    return <div className="web-app-shell">
      <aside className="web-sidebar">
        <div className="web-brand"><span><Sparkles size={18}/></span><strong>orbitask</strong><ChevronDown size={15}/></div>
        <button className="web-create" onClick={()=>openCreate()}><Plus size={18}/> Criar</button>
        <nav className="web-primary-nav">
          <button className={page==='reports'?'active':''} onClick={()=>setPage('reports')}><LayoutDashboard size={18}/> Visão geral</button>
          <button><CheckSquare2 size={18}/> Minhas tarefas <em>{snapshot.tasks.length}</em></button>
          <button className={page==='portfolios'?'active':''} onClick={()=>setPage('portfolios')}><BriefcaseBusiness size={18}/> Portfólios</button>
          <button className={page==='team'?'active':''} onClick={()=>setPage('team')}><Users size={18}/> Pessoas <em>{snapshot.members.length}</em></button>
          <button className={page==='inbox'?'active':''} onClick={()=>setPage('inbox')}><Bell size={18}/> Caixa de entrada <i/></button>
        </nav>
        <div className="web-nav-title"><span>Projetos</span><button aria-label="Novo projeto"><Plus size={15}/></button></div>
        <nav className="web-projects">{snapshot.projects.map(project=><button className={project.id===snapshot.project.id?'active':''} key={project.id} onClick={()=>{loadSnapshot(project.id);setPage('project')}}><i className="web-project-glyph" style={{background:project.color}}><ProjectGlyph name={project.icon}/></i>{project.name}</button>)}</nav>
        <div className="web-sidebar-footer"><button onClick={()=>setPage('team')}><Users size={18}/> Pessoas e acesso</button><button><Settings size={18}/> Configurações</button><button onClick={signOut}>Sair da conta</button></div>
      </aside>
      <main className="web-workspace">
        <header className="web-topbar">
          <label className="web-global-search" ref={searchRef}><Search size={18}/><input value={query} onFocus={()=>setSearchOpen(true)} onChange={e=>{setQuery(e.target.value);setSearchOpen(true)}} placeholder="Buscar tarefas, projetos ou pessoas..."/><kbd>⌘ K</kbd>{searchOpen&&<div className="web-search-palette" onPointerDown={event=>event.stopPropagation()}>{query.trim().length<2?<section><h4><History/> Buscas recentes</h4>{searchResult.recent.length?searchResult.recent.map(item=><button key={item} onClick={()=>setQuery(item)}><History/><span>{item}</span></button>):<p>Suas buscas recentes aparecerão aqui.</p>}</section>:<>{searchResult.tasks.length>0&&<section><h4>Tarefas</h4>{searchResult.tasks.map(item=><button key={item.id} onClick={async()=>{const next=item.projectId===snapshot.project.id?snapshot:await loadSnapshot(item.projectId);setPage('project');setSearchOpen(false);const task=next.tasks.find(task=>task.id===item.id);if(task)openTask(task)}}><i style={{background:item.statusColor}}/><span><strong>{item.title}</strong><small>{item.projectName} · {item.statusName}</small></span></button>)}</section>}{searchResult.projects.length>0&&<section><h4>Projetos</h4>{searchResult.projects.map(item=><button key={item.id} onClick={()=>{loadSnapshot(item.id);setPage('project');setSearchOpen(false)}}><span className="web-search-icon" style={{background:item.color}}><ProjectGlyph name={item.icon}/></span><span><strong>{item.name}</strong><small>{item.description||'Projeto da equipe'}</small></span></button>)}</section>}{searchResult.people.length>0&&<section><h4>Pessoas</h4>{searchResult.people.map(item=><button key={item.id} onClick={()=>{setAdvancedFilter({...advancedFilter,assigneeIds:[item.id]});setPage('project');setSearchOpen(false)}}><span className="web-search-avatar">{item.name.split(' ').map(part=>part[0]).slice(0,2).join('')}</span><span><strong>{item.name}</strong><small>{item.email}</small></span></button>)}</section>}{!searchResult.tasks.length&&!searchResult.projects.length&&!searchResult.people.length&&<div className="web-search-empty"><Search/><strong>Nenhum resultado</strong><span>Tente outro termo ou confira a escrita.</span></div>}</>}</div>}</label>
          <button className="web-icon-button" aria-label="Notificações" onClick={()=>setPage('inbox')}><Bell size={19}/></button>
          <button className="web-profile" title={session.user.email}>{initials}</button>
        </header>
        {page==='reports'?<WebReportsPage/>:page==='portfolios'?<WebPortfoliosPage snapshot={snapshot}/>:page==='team'?<WebTeamPage snapshot={snapshot} session={session} onRefresh={async()=>{await loadSnapshot(snapshot.project.id)}} onSession={setSession}/>:page==='inbox'?<WebInboxPage snapshot={snapshot} onOpen={task=>{setPage('project');openTask(task)}}/>:page==='automations'?<WebAutomationsPage snapshot={snapshot} onBack={()=>setPage('project')}/>:<><section className="web-project-header">
          <div><small>Projetos / {snapshot.workspace.name}</small><h1><span style={{background:snapshot.project.color}}><ProjectGlyph name={snapshot.project.icon}/></span>{snapshot.project.name}<ChevronDown size={18}/></h1></div>
          <div><button><Users size={17}/> Compartilhar</button><button className="web-icon-button"><MoreHorizontal size={19}/></button></div>
        </section>
        <section className="web-toolbar">
          <nav><button className={view==='board'?'active':''} onClick={()=>changeView('board')}><LayoutDashboard size={17}/> Quadro</button><button className={view==='list'?'active':''} onClick={()=>changeView('list')}><ListChecks size={17}/> Lista</button><button className={view==='calendar'?'active':''} onClick={()=>setView('calendar')}><CalendarDays size={17}/> Calendário</button><button className={view==='timeline'?'active':''} onClick={()=>setView('timeline')}><BarChart3 size={17}/> Cronograma</button></nav>
          <div className="web-toolbar-actions"><span className="web-filter-wrap" ref={filterRef}><button className={activeFilterCount(advancedFilter)||customFilter.fieldId||filtersOpen?'active':''} aria-expanded={filtersOpen} onClick={()=>setFiltersOpen(!filtersOpen)}><Filter size={17}/> Filtrar {activeFilterCount(advancedFilter)>0&&<b>{activeFilterCount(advancedFilter)}</b>}</button>{filtersOpen&&<WebAdvancedFilters snapshot={snapshot} value={advancedFilter} onChange={setAdvancedFilter} onClose={()=>setFiltersOpen(false)}/>}</span><button onClick={()=>setPage('automations')}><Zap size={17}/> Automações</button><button onClick={()=>setCustomFieldsOpen(true)}><Workflow size={17}/> Campos</button><button onClick={toggleDensity}><Settings size={17}/> {snapshot.preferences.cardDensity==='compact'?'Cards detalhados':'Cards compactos'}</button><button className="web-new-task" onClick={()=>openCreate()}><Plus size={17}/> Nova tarefa</button></div>
        </section>
        {view==='calendar'?<WebCalendarView snapshot={snapshot} tasks={tasks} onOpen={openTask} onRefresh={async()=>{await loadSnapshot(snapshot.project.id)}}/>:view==='timeline'?<WebTimelineView snapshot={snapshot} tasks={tasks} onOpen={openTask}/>:view==='board'?<section className={`web-board ${snapshot.preferences.cardDensity==='compact'?'compact':''}`}>
          {snapshot.statuses.map(status=>{const columnTasks=tasks.filter(task=>task.statusId===status.id);return <div className="web-column" key={status.id}>
            <header style={{background:status.color}} onDragOver={event=>event.preventDefault()} onDrop={event=>moveTask(event.dataTransfer.getData('text/task-id'),status.id)}><strong>{status.name}</strong><span>{columnTasks.length}</span><button onClick={()=>openCreate(status.id)} aria-label={`Adicionar em ${status.name}`}><Plus size={17}/></button></header>
            <div className="web-task-list" onDragOver={event=>event.preventDefault()} onDrop={event=>moveTask(event.dataTransfer.getData('text/task-id'),status.id)}>{columnTasks.filter(task=>!task.parentId).map(task=>{const priority=snapshot.settings.priorities.find(item=>item.id===task.priority),owner=snapshot.members.find(member=>member.userId===task.primaryAssigneeId);return <button draggable onDragStart={event=>event.dataTransfer.setData('text/task-id',task.id)} className="web-task-card" style={{'--status-color':status.color} as React.CSSProperties} key={task.id} onClick={()=>openTask(task)}><div><small style={{color:priority?.color,background:`${priority?.color}14`}}>{priority?.name??task.priority}</small><MoreHorizontal size={17}/></div><strong>{task.title}</strong><p>{task.description||'Adicione contexto e detalhes para sua equipe.'}</p><WebCustomFieldSummary snapshot={snapshot} task={task}/><footer><span className="web-mini-avatar">{owner?.avatarUrl?<img src={owner.avatarUrl}/>:owner?.name.slice(0,2).toUpperCase()??'—'}</span>{task.assigneeIds.length>1&&<b>+{task.assigneeIds.length-1}</b>}<span>{task.dueDate?<><Clock3 size={14}/>{new Date(`${task.dueDate}T12:00:00`).toLocaleDateString('pt-BR',{day:'2-digit',month:'short'})}</>:<><CheckSquare2 size={14}/> Sem prazo</>}</span></footer></button>})}</div>
            {columnTasks.length===0&&<div className="web-empty-column"><FolderKanban size={22}/><span>Nenhuma tarefa aqui</span></div>}
            <button className="web-add-inline" onClick={()=>openCreate(status.id)}><Plus size={16}/> Adicionar tarefa</button>
          </div>})}
        </section>:<WebFilteredList snapshot={snapshot} tasks={tasks} group={advancedFilter.group} onOpen={openTask}/>}</>}
      </main>
      {customFieldsOpen&&<WebCustomFieldsModal snapshot={snapshot} onClose={()=>setCustomFieldsOpen(false)} onRefresh={async()=>{await loadSnapshot(snapshot.project.id)}}/>}
      {(createOpen||selectedTask)&&<div className="web-modal-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget){setCreateOpen(false);setSelectedTask(null)}}}><form className="web-task-modal" onSubmit={selectedTask?updateTask:createTask}>
        <header><div><small>{selectedTask?'EDITAR TAREFA':'NOVA TAREFA'}</small><h2>{selectedTask?'Detalhes da tarefa':'Transforme uma ideia em ação'}</h2></div><button type="button" onClick={()=>{setCreateOpen(false);setSelectedTask(null)}}><X size={20}/></button></header>
        <label>Título<input autoFocus required value={taskForm.title} onChange={e=>setTaskForm({...taskForm,title:e.target.value})} placeholder="O que precisa ser feito?"/></label>
        <label>Descrição<textarea rows={4} value={taskForm.description} onChange={e=>setTaskForm({...taskForm,description:e.target.value})} placeholder="Adicione contexto, objetivo ou critérios de conclusão..."/></label>
        <div className="web-task-fields"><label>Status<select value={taskForm.statusId} onChange={e=>setTaskForm({...taskForm,statusId:e.target.value})}>{snapshot.statuses.map(status=><option key={status.id} value={status.id}>{status.name}</option>)}</select></label><label>Prioridade<select value={taskForm.priority} onChange={e=>setTaskForm({...taskForm,priority:e.target.value as Priority})}>{snapshot.settings.priorities.map(item=><option key={item.id} value={item.id}>{item.name}</option>)}</select></label></div>
        <div className="web-task-fields"><label>Início<input type="date" value={taskForm.startDate} onChange={e=>setTaskForm({...taskForm,startDate:e.target.value})}/></label><label>Término<input type="date" min={taskForm.startDate||undefined} value={taskForm.dueDate} onChange={e=>setTaskForm({...taskForm,dueDate:e.target.value})}/></label></div>
        <fieldset className="web-people-picker"><legend>Responsáveis</legend>{snapshot.members.map(member=><label key={member.userId}><input type="checkbox" checked={taskForm.assigneeIds.includes(member.userId)} onChange={()=>{const ids=taskForm.assigneeIds.includes(member.userId)?taskForm.assigneeIds.filter(id=>id!==member.userId):[...taskForm.assigneeIds,member.userId];setTaskForm({...taskForm,assigneeIds:ids,primaryAssigneeId:ids.includes(taskForm.primaryAssigneeId)?taskForm.primaryAssigneeId:(ids[0]??'')})}}/>{member.name}</label>)}</fieldset>
        <label>Responsável principal<select value={taskForm.primaryAssigneeId} onChange={e=>setTaskForm({...taskForm,primaryAssigneeId:e.target.value})}><option value="">Sem responsável principal</option>{snapshot.members.filter(member=>taskForm.assigneeIds.includes(member.userId)).map(member=><option key={member.userId} value={member.userId}>{member.name}</option>)}</select></label>
        <fieldset className="web-people-picker"><legend>Seguidores</legend>{snapshot.members.map(member=><label key={member.userId}><input type="checkbox" checked={taskForm.followerIds.includes(member.userId)} onChange={()=>setTaskForm({...taskForm,followerIds:taskForm.followerIds.includes(member.userId)?taskForm.followerIds.filter(id=>id!==member.userId):[...taskForm.followerIds,member.userId]})}/>{member.name}</label>)}</fieldset>
        {selectedTask&&<WebTaskExtras snapshot={snapshot} task={selectedTask} onRefresh={async()=>{await loadSnapshot(snapshot.project.id)}} onOpen={openTask}/>}
        {error&&<div className="web-error">{error}</div>}
        <footer><button type="button" onClick={()=>{setCreateOpen(false);setSelectedTask(null)}}>Cancelar</button><button className="web-save-task" disabled={busy}>{busy?'Salvando...':selectedTask?'Salvar alterações':'Criar tarefa'}</button></footer>
      </form></div>}
    </div>
  }

  if(inviteToken){return <><Nav/><main className="web-auth"><section><small>CONVITE PARA O ORBITASK</small><h1>{inviteInfo?`Entre em ${inviteInfo.workspaceName}`:'Abrindo convite...'}</h1>{inviteInfo&&<><p>{inviteInfo.invitedByName} convidou <strong>{inviteInfo.email}</strong> como {inviteInfo.role==='guest'?'convidado':'membro'}.</p><form onSubmit={acceptInvite}><label>Seu nome<input required value={inviteForm.name} onChange={e=>setInviteForm({...inviteForm,name:e.target.value})}/></label><label>Senha<input required minLength={8} type="password" value={inviteForm.password} onChange={e=>setInviteForm({...inviteForm,password:e.target.value})}/></label>{error&&<div className="web-error">{error}</div>}<button disabled={busy}>{busy?'Entrando...':'Aceitar convite'}</button></form></>}</section></main><Footer/></>}

  return <><Nav/><main className="web-auth"><section><small>ORBITASK WEB</small><h1>{mode==='signup'?'Crie sua conta grátis':'Bem-vindo de volta'}</h1><p>{mode==='signup'?'Seu workspace e primeiro projeto serão criados automaticamente.':'Entre para acessar seus projetos e tarefas.'}</p><form onSubmit={submit}>{mode==='signup'&&<><label>Seu nome<input required value={form.name} onChange={e=>setForm({...form,name:e.target.value})}/></label><label>Workspace<input value={form.workspaceName} onChange={e=>setForm({...form,workspaceName:e.target.value})} placeholder="Nome da empresa ou equipe"/></label></>}<label>E-mail<input required type="email" value={form.email} onChange={e=>setForm({...form,email:e.target.value})}/></label><label>Senha<input required minLength={8} type="password" value={form.password} onChange={e=>setForm({...form,password:e.target.value})}/></label>{error&&<div className="web-error">{error}</div>}<button disabled={busy}>{busy?'Aguarde...':mode==='signup'?'Criar conta':'Entrar'}</button></form><button className="mode-switch" onClick={()=>setMode(mode==='login'?'signup':'login')}>{mode==='login'?'Não tem conta? Cadastre-se':'Já tem conta? Entre'}</button></section></main><Footer/></>
}

const path = window.location.pathname
const Page = path.startsWith('/download') ? DownloadPage : path.startsWith('/novidades') ? ReleasesPage : path.startsWith('/app') ? WebAppPage : Home
ReactDOM.createRoot(document.getElementById('root')!).render(<React.StrictMode><Page/></React.StrictMode>)
